/** The OPTIONAL condition belongs to each merged occurrence, including equal left input rows. */
@ResourceLock(Resources.SYSTEM_PROPERTIES)
class NativeCorrelatedOptionalConditionTest {
	private static final String NATIVE = "rdf4j.lmdb.nativeQueryEngine.enabled";
	private static final String NS = "urn:optional-condition-occurrence:";
	private static final String FUNCTION = NS + "alternating";

	@Test
	void factorizedDuplicatesEvaluateTheOptionalConditionSeparately() throws IOException {
		NativeSlotLayout layout = new NativeSlotLayout(Map.of("value", 0), null);
		layout.freeze(List.of("value"));
		RowState row = new RowState(null, layout, EmptyBindingSet.getInstance());
		NativeRowSeeder.seed(row.slots, layout, row.base, null);
		row.recomputeBoundMask();
		AtomicInteger calls = new AtomicInteger();
		SlotPlan left = new SlotPlan() {
			@Override
			public RowCursor open(RowState input) {
				return new FactorizedRowCursor() {
					private boolean emitted;

					@Override
					public boolean next() {
						if (emitted) {
							return false;
						}
						emitted = true;
						return true;
					}

					@Override
					public long multiplicity() {
						return 2L;
					}

					@Override
					public void close() {
					}
				};
			}

			@Override
			public long producedMask() {
				return 0L;
			}
		};
		SlotPlan matches = SlotPlan.values(new ValuesRow[] { new ValuesRow(new int[] { 0 }, new long[] { 42L }) });
		SlotPlan condition = new FilterPlan(matches, ignored -> (calls.incrementAndGet() & 1) != 0, 0L);
		LeftJoinPlan optional = new LeftJoinPlan(left, condition, null, false, null, null,
				OptionalRhsContract.unknown(), true);
		List<Long> output = new ArrayList<>();
		try (RowCursor cursor = LmdbNativeFactorRows.asRows(LmdbNativeFactorAlgebra.open(optional, row), row)) {
			while (cursor.next()) {
				long weight = cursor instanceof FactorizedRowCursor factor ? factor.multiplicity() : 1L;
				for (long occurrence = 0; occurrence < weight; occurrence++) {
					output.add(row.slots[0]);
				}
			}
		} finally {
			row.memoryScope.close();
		}
		assertThat(output).containsExactly(42L, NativeLmdbQuerySource.UNKNOWN_ID);
		assertThat(calls).hasValue(2);
	}

	@Test
	void volatileCorrelatedConditionIsNeverReplayedAsAQualifyingMatch(@TempDir File directory) {
		String previousNative = System.getProperty(NATIVE);
		FunctionRegistry registry = FunctionRegistry.getInstance();
		Function previousFunction = registry.get(FUNCTION).orElse(null);
		Alternating condition = new Alternating();
		registry.add(condition);
		SailRepository repository = new SailRepository(new LmdbStore(directory,
				new LmdbStoreConfig("spoc,posc,ospc").setNativeEvaluationEnabled(true)));
		String query = "PREFIX ex: <" + NS + "> SELECT ?s ?value WHERE { "
				+ "VALUES ?s { ex:seed ex:seed } OPTIONAL { ?s ex:value ?value . "
				+ "FILTER(ex:alternating(?s)) } }";
		try {
			try (var connection = repository.getConnection()) {
				var vf = connection.getValueFactory();
				connection.add(vf.createIRI(NS, "seed"), vf.createIRI(NS, "value"), vf.createLiteral(7));
			}
			System.setProperty(NATIVE, "false");
			List<String> generic = rows(repository, query, false);
			assertThat(generic).containsExactlyInAnyOrder(NS + "seed|7", NS + "seed|null");
			assertThat(condition.calls).hasValue(2);
			condition.calls.set(0);
			System.setProperty(NATIVE, "true");
			try (var connection = repository.getConnection()) {
				SailTupleQuery audit = (SailTupleQuery) connection.prepareTupleQuery(query);
				audit.setForcedLmdbExecutionStrategy("nestedLoop");
				assertThat(audit.explain(Explanation.Level.Executed).toString()).contains("NativeRows", "LeftJoin");
			}
			condition.calls.set(0);
			assertThat(rows(repository, query, true)).containsExactlyInAnyOrderElementsOf(generic);
			assertThat(condition.calls).as("the condition runs for both merged duplicate occurrences").hasValue(2);
		} finally {
			repository.shutDown();
			registry.remove(condition);
			if (previousFunction != null) {
				registry.add(previousFunction);
			}
			if (previousNative == null) {
				System.clearProperty(NATIVE);
			} else {
				System.setProperty(NATIVE, previousNative);
			}
		}
	}

	private static List<String> rows(SailRepository repository, String query, boolean forceNative) {
		try (var connection = repository.getConnection()) {
			SailTupleQuery prepared = (SailTupleQuery) connection.prepareTupleQuery(query);
			if (forceNative) {
				prepared.setForcedLmdbExecutionStrategy("nestedLoop");
			}
			return QueryResults.asList(prepared.evaluate())
					.stream()
					.map(NativeCorrelatedOptionalConditionTest::row)
					.toList();
		}
	}

	private static String row(BindingSet bindings) {
		Value value = bindings.getValue("value");
		return bindings.getValue("s").stringValue() + "|" + (value == null ? "null" : value.stringValue());
	}

	private static final class Alternating implements Function {
		final AtomicInteger calls = new AtomicInteger();

		@Override
		public String getURI() {
			return FUNCTION;
		}

		@Override
		public Determinism getDeterminism() {
			return Determinism.VOLATILE;
		}

		@Override
		public Value evaluate(ValueFactory factory, Value... values) throws ValueExprEvaluationException {
			if (values.length != 1) {
				throw new ValueExprEvaluationException("expected one argument");
			}
			return factory.createLiteral((calls.incrementAndGet() & 1) != 0);
		}
	}
}
